def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/astronomy/input/TLE/43180.tle'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        lines = [ln.rstrip('\n') for ln in f if ln.strip() != '']
    return pd.DataFrame({'line': lines})

def process(bestLag) -> pd.DataFrame:
    import pandas as pd
    if bestLag is None or bestLag.empty:
        return pd.DataFrame([{"bestLagHours": None}])
    return pd.DataFrame([{"bestLagHours": int(bestLag.iloc[0]["lagHours"])}])
